import pandas as pd,numpy as np
from pathlib import Path
P=Path('outputs/最近两周三模型_20261113');O=P/'十一月F风控_20261114';O.mkdir(exist_ok=True);a=pd.read_pickle(P/'十一月每日名单.pkl.gz');b=pd.read_pickle(P/'十三日全部候选与排名.pkl.gz');b=b[b[['每日滚动排名','每月训练排名','六训二验排名']].le(2).any(axis=1)].copy();x=pd.concat([a,b],ignore_index=True);assert len(x)==46 and x.d0_date.nunique()==10 and not x.duplicated(['d0_date','symbol']).any()
for name,alias in [('选中池_F','选中池'),('全涨停池_F','全池')]:
 m=np.load(Path('outputs/三模型全月_20261113/D0预测弱势与撤单_20261114')/f'{name}_2026_numpy模型.npz',allow_pickle=False);features=list(m['features']);v=x[features].apply(pd.to_numeric,errors='coerce').replace([np.inf,-np.inf],np.nan).to_numpy(float);missing=~np.isfinite(v);v=np.where(missing,m['median'],v);v=np.clip((v-m['median'])/m['scale'],-5,5);np.seterr(all='ignore');z=np.column_stack([np.ones(len(v)),v,np.maximum(v-1,0),np.maximum(-v-1,0),missing.astype(float)]);x[alias+'分数']=1/(1+np.exp(-(z@m['weights'])));x[alias+'阈值']=m['thresholds'][1];x[alias+'命中']=x[alias+'分数']>=m['thresholds'][1]
x['排除']=x['选中池命中']|x['全池命中'];names=pd.read_csv(P/'十一月十三日行情与名称.csv',dtype={'symbol':str});nm=dict(zip(names.symbol,names.名称));names13=pd.read_csv(P/'十三日三模型候选.csv',dtype={'symbol':str});nm.update(dict(zip(names13.symbol,names13['name'])));x['股票名称']=x.symbol.map(nm);x.to_pickle(O/'候选风险分数.pkl.gz');x[['d0_date','symbol','股票名称','选中池分数','选中池阈值','选中池命中','全池分数','全池阈值','全池命中','排除','票数','每日滚动排名','每月训练排名','六训二验排名']].to_csv(O/'风险明细.csv',index=False,encoding='utf-8-sig');print(x[['d0_date','symbol','股票名称','选中池分数','选中池命中','全池分数','全池命中','排除']].to_string(index=False));print('hit',x.排除.sum(),'remaining',(~x.排除).sum())
